#!/usr/bin/env bash
# Lint, passe 2 : les 16 règles du React Compiler réglées, lint à zéro et ajouté à pnpm check
# (--max-warnings 0) ; chapitre « Qualité / Le typecheck et le lint » ; docs : précédent / suivant dans
# l'ordre de lecture, pourcentage entre les flèches.
# Prérequis : apply-lint-passe-1.sh et apply-docs-pastilles-v2.sh.
# Usage (racine du repo) : bash apply-lint-passe-2.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" 2>/dev/null | grep -qF "Le typecheck et le lint"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Une page en brouillon n’est" "apps/web/src/app/(admin)/dashboard/pages/page.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-lint-passe-1.sh"; exit 1; }
grep -qF "Sur cette page" "apps/web/src/features/docs/components/DocsRightAsideDrawer.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-pastilles-v2.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/eslint.config.mjs" "apps/web/package.json" "apps/web/src/app/(admin)/dashboard/settings/page.tsx" "apps/web/src/app/(admin)/dashboard/site-pages/home/page.tsx" "apps/web/src/app/(public)/documents/page.tsx" "apps/web/src/features/admin/galleries/forms/CreateGalleryForm.tsx" "apps/web/src/features/admin/galleries/forms/UpdateGalleryForm.tsx" "apps/web/src/features/admin/perso/PersoPhotoUploader.tsx" "apps/web/src/features/breaking-news/BreakingNewsShell.tsx" "apps/web/src/features/docs/components/DocsLayout.tsx" "apps/web/src/features/docs/components/DocsMainScrollControls.tsx" "apps/web/src/features/docs/entities/EntityExplorer.tsx" "apps/web/src/features/docs/lib/docs.navigation.ts" "apps/web/src/features/finder-core/hooks/useNodeActions.ts" "apps/web/src/features/finder-core/hooks/useStatusChange.ts" "apps/web/src/features/gallery-crop/components/Cropper.tsx" "apps/web/src/features/page-builder/blocks/float-text/FloatTextPreview.tsx" "apps/web/src/features/page-builder/blocks/media-text/MediaTextPreview.tsx" "apps/web/src/features/page-builder/components/useResolvedMediaList.ts" "package.json")
CREATED=("apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" "apps/web/src/features/page-builder/components/useResolvedPreviewMedia.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Le typecheck et le lint" "apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/qualite"
base64 -d > "apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" <<'B64'
